public class Solution {
    public List<List<Integer>> verticalTraversal(TreeNode root) {
        TreeMap<Integer, TreeMap<Integer, PriorityQueue<Integer>>> map = new TreeMap<>();
        Queue<Tuple> q = new LinkedList<>();
        q.add(new Tuple(root, 0, 0));
        while (!q.isEmpty()) {
            Tuple t = q.poll();
            map.putIfAbsent(t.col, new TreeMap<>());
            map.get(t.col).putIfAbsent(t.row, new PriorityQueue<>());
            map.get(t.col).get(t.row).add(t.node.val);
            if (t.node.left != null) q.add(new Tuple(t.node.left, t.col - 1, t.row + 1));
            if (t.node.right != null) q.add(new Tuple(t.node.right, t.col + 1, t.row + 1));
        }
        List<List<Integer>> res = new ArrayList<>();
        for (TreeMap<Integer, PriorityQueue<Integer>> cols : map.values()) {
            List<Integer> colVals = new ArrayList<>();
            for (PriorityQueue<Integer> pq : cols.values()) {
                while (!pq.isEmpty()) colVals.add(pq.poll());
            }
            res.add(colVals);
        }
        return res;
    }
    static class Tuple {
        TreeNode node; int col, row;
        Tuple(TreeNode n, int c, int r) { node = n; col = c; row = r; }
    }
}

