def boundaryOfBinaryTree(root: TreeNode) -> list[int]:
    if not root: return []
    def is_leaf(n):
        return n and not n.left and not n.right

    res = []
    if not is_leaf(root): res.append(root.val)

    # Left Boundary
    curr = root.left
    while curr:
        if not is_leaf(curr): res.append(curr.val)
        curr = curr.left if curr.left else curr.right

    # Leaves
    def add_leaves(n):
        if not n: return
        if is_leaf(n): res.append(n.val)
        else:
            add_leaves(n.left)
            add_leaves(n.right)
    add_leaves(root)

    # Right Boundary Reverse
    right_b = []
    curr = root.right
    while curr:
        if not is_leaf(curr): right_b.append(curr.val)
        curr = curr.right if curr.right else curr.left
    res.extend(reversed(right_b))
    return res

