class Solution {
    bool isLeaf(TreeNode* n) { return n && !n->left && !n->right; }
    void addLeaves(TreeNode* n, vector<int>& res) {
        if (!n) return;
        if (isLeaf(n)) res.push_back(n->val);
        else {
            addLeaves(n->left, res);
            addLeaves(n->right, res);
        }
    }
public:
    vector<int> boundaryOfBinaryTree(TreeNode* root) {
        if (!root) return {};
        vector<int> res;
        if (!isLeaf(root)) res.push_back(root->val);
        TreeNode* curr = root->left;
        while (curr) {
            if (!isLeaf(curr)) res.push_back(curr->val);
            curr = curr->left ? curr->left : curr->right;
        }
        addLeaves(root, res);
        vector<int> rightB;
        curr = root->right;
        while (curr) {
            if (!isLeaf(curr)) rightB.push_back(curr->val);
            curr = curr->right ? curr->right : curr->left;
        }
        for (int i = rightB.size() - 1; i >= 0; i--) res.push_back(rightB[i]);
        return res;
    }
};

