public class Solution {
    private boolean isLeaf(TreeNode n) { return n != null && n.left == null && n.right == null; }
    public List<Integer> boundaryOfBinaryTree(TreeNode root) {
        List<Integer> res = new ArrayList<>();
        if (root == null) return res;
        if (!isLeaf(root)) res.add(root.val);
        TreeNode curr = root.left;
        while (curr != null) {
            if (!isLeaf(curr)) res.add(curr.val);
            curr = curr.left != null ? curr.left : curr.right;
        }
        addLeaves(root, res);
        List<Integer> rightB = new ArrayList<>();
        curr = root.right;
        while (curr != null) {
            if (!isLeaf(curr)) rightB.add(curr.val);
            curr = curr.right != null ? curr.right : curr.left;
        }
        for (int i = rightB.size() - 1; i >= 0; i--) res.add(rightB.get(i));
        return res;
    }
    private void addLeaves(TreeNode n, List<Integer> res) {
        if (n == null) return;
        if (isLeaf(n)) res.add(n.val);
        else {
            addLeaves(n.left, res);
            addLeaves(n.right, res);
        }
    }
}

