            for (int i = 0; i < sz; i++) {
                TreeNode* curr = q.front(); q.pop();
                for (TreeNode* nextNode : {curr->left, curr->right, parents[curr]}) {
                    if (nextNode && !visited.count(nextNode)) {
                        visited.insert(nextNode);
                        q.push(nextNode);
                    }
                }
            }
        }
        return time;
    }
};

