public class Solution {
    private Map<TreeNode, TreeNode> parents = new HashMap<>();
    private TreeNode targetNode = null;
    public int amountOfTime(TreeNode root, int start) {
        dfs(root, start, null);
        Queue<TreeNode> q = new LinkedList<>();
        Set<TreeNode> visited = new HashSet<>();
        q.add(targetNode);
        visited.add(targetNode);
        int time = -1;
        while (!q.isEmpty()) {
            int sz = q.size();
            time++;
            for (int i = 0; i < sz; i++) {
                TreeNode curr = q.poll();
                for (TreeNode next : Arrays.asList(curr.left, curr.right, parents.get(curr))) {
                    if (next != null && !visited.contains(next)) {
                        visited.add(next);
                        q.add(next);
                    }
                }
            }
        }
        return time;
    }
    private void dfs(TreeNode node, int start, TreeNode par) {
        if (node == null) return;
        if (node.val == start) targetNode = node;
        parents.put(node, par);
        dfs(node.left, start, node);
        dfs(node.right, start, node);
    }
}

