class TreeAncestor {
  constructor(n, parent) {
    this.LOG = 16;
    this.up = Array.from({ length: n }, () => new Array(this.LOG).fill(-1));
    for (let i = 0; i < n; i++) this.up[i][0] = parent[i];
    for (let j = 1; j < this.LOG; j++) {
      for (let i = 0; i < n; i++) {
        if (this.up[i][j-1] !== -1) {
          this.up[i][j] = this.up[this.up[i][j-1]][j-1];
        }
      }
    }
  }
  getKthAncestor(node, k) {
    for (let j = 0; j < this.LOG; j++) {
      if ((k >> j) & 1) {
        node = this.up[node][j];
        if (node === -1) break;
      }
    }
    return node;
  }
}

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def buildTree(preorder: list[int], inorder: list[int]) -> TreeNode:
    in_map = {val: i for i, val in enumerate(inorder)}
    pre_idx = 0
    def helper(in_left, in_right):
        nonlocal pre_idx
        if in_left > in_right:
            return None
        root_val = preorder[pre_idx]
        pre_idx += 1
        root = TreeNode(root_val)
        idx = in_map[root_val]
        root.left = helper(in_left, idx - 1)
        root.right = helper(idx + 1, in_right)
        return root
    return helper(0, len(inorder) - 1)

