        if (q.empty()) return nullptr;
        string val = q.front(); q.pop();
        if (val == "null") return nullptr;
        TreeNode* node = new TreeNode(stoi(val));
        node->left = helper(q);
        node->right = helper(q);
        return node;
    }
};

